from __future__ import annotations; import re; import shlex; import subprocess; from pathlib import Path; import pytest; REPO_ROOT = Path(__file__).resolve().parents[3]; APPLIER = "db/apply_migrations.sh"; SHELL_CHAIN_LOOP = re.compile(r"for\s+\w+\s+in\s+[^\n;]*migrations/\*\.sql"); PYTHON_CHAIN_GLOB = re.compile(r"\.glob\(\s*[\"']\*\.sql[\"']\s*\)"); PYTHON_CHAIN_EXECUTES = ( re.compile(r"[\"']psql[\"']"), re.compile(r"execute\(\s*[\w.]+\.read_text\(\)"), ); COPIES_THAT_EXISTED = ( ("ci-python.yml", "          for f in db/migrations/*.sql db/roles.sql; do"), ("ci-db.yml", "          for f in db/migrations/*.sql db/roles.sql; do"), ("ci-web.yml", "            for f in db/migrations/*.sql db/roles.sql; do"), ("db/apply_migrations.sh", 'for migration in "$db_dir"/migrations/*.sql "$db_dir"/roles.sql; do'), ("Makefile", "\t\tfor f in db/migrations/*.sql db/roles.sql; do \\"), ("db/docker-init.sh", 'for migration in "$db_dir"/migrations/*.sql "$db_dir"/roles.sql; do'), ("setup_vps_ingest.sh", "for f in db/migrations/*.sql db/roles.sql; do"), ); PYTHON_COPIES_THAT_EXISTED = ( ( "production_topt fixtures", 'for migration in (*sorted((ROOT / "db/migrations").glob("*.sql")), ROOT / "db/roles.sql"):\n    subprocess.run(["psql", target_url, "-v", "ON_ERROR_STOP=1", "-f", str(migration)])', ), ( "test_entity_identity_store.fresh_databases", 'for migration in sorted(MIGRATIONS.glob("*.sql")):\n    fresh.execute(migration.read_text())', ), ); _SKIP_SUFFIXES = {".png", ".jpg", ".jpeg", ".gif", ".ico", ".pdf", ".woff", ".woff2", ".zip", ".gz", ".lock"}
def _tracked_files() -> list[Path]: listing = subprocess.run( ["git", "ls-files", "-z"], cwd=REPO_ROOT, capture_output=True, text=True, check=True ).stdout; return [REPO_ROOT / name for name in listing.split("\0") if name]
def _scannable() -> list[Path]:
    myself = Path(__file__).resolve(); scanned = []
    for path in _tracked_files():
        if path.suffix.lower() in _SKIP_SUFFIXES or not path.is_file(): continue
        if path.resolve() == myself: continue
        scanned.append(path)
    return scanned
def _text(path: Path) -> str | None:
    try: return path.read_text(encoding="utf-8")
    except (UnicodeDecodeError, OSError): return None
def test_only_one_file_applies_the_migration_chain() -> None:
    offenders: list[str] = []; scanned = 0
    for path in _scannable():
        body = _text(path)
        if body is None: continue
        scanned += 1; relative = path.relative_to(REPO_ROOT).as_posix()
        if relative == APPLIER: continue
        if SHELL_CHAIN_LOOP.search(body): offenders.append(f"{relative}: a shell loop over db/migrations/*.sql")
        if path.suffix == ".py" and PYTHON_CHAIN_GLOB.search(body):
            if any(pattern.search(body) for pattern in PYTHON_CHAIN_EXECUTES): offenders.append(f"{relative}: globs the chain and executes what it finds")
    assert scanned > 500, f"the scan only read {scanned} files — it is not looking at the tree"
    assert not offenders, ( "the migration chain is applied somewhere other than db/apply_migrations.sh:\n  " + "\n  ".join(offenders) + f'\n\nEvery call site runs {APPLIER}; it takes MIGRATIONS_DATABASE_URL/DATABASE_URL, TRUEALPHA_PSQL (when psql runs in a container) and TRUEALPHA_DB_DIR. A second copy is how the seven diverged (#984).' )
def test_the_detectors_recognise_every_copy_that_existed_before() -> None:
    for where, line in COPIES_THAT_EXISTED: assert SHELL_CHAIN_LOOP.search(line), f"the shell detector no longer matches the copy from {where}: {line!r}"
    for where, body in PYTHON_COPIES_THAT_EXISTED: assert PYTHON_CHAIN_GLOB.search(body) and any(p.search(body) for p in PYTHON_CHAIN_EXECUTES), ( f"the Python detector no longer matches the copy from {where}" )
def test_the_detectors_leave_readers_alone() -> None:
    readers = ( "common/runtime/src/truealpha_tools/check_factor_contract.py", "common/runtime/tests/test_migration_chain.py", "common/runtime/tests/test_migration_vocabularies.py", "apps/data-engine/src/data_engine/release_identity.py", "apps/data-engine/tests/test_release_identity.py", "apps/data-engine/tests/test_entity_identity_store.py", )
    for relative in readers: path = REPO_ROOT / relative; assert path.exists(), f"{relative} is gone; this test's premise moved"; body = path.read_text(encoding="utf-8"); assert PYTHON_CHAIN_GLOB.search(body), f"{relative} no longer globs the chain — drop it from this list"; assert not any(pattern.search(body) for pattern in PYTHON_CHAIN_EXECUTES), ( f"{relative} now executes what it globs, so it is a second applier or the detector is wrong" )
FILE_CALL_SITES = { "Makefile": (APPLIER, "db/reset_database.sh"), "db/docker-init.sh": ("apply_migrations.sh",), "db/reset_database.sh": ("apply_migrations.sh",), "apps/data-engine/scripts/setup_vps_ingest.sh": (APPLIER,), "apps/llm-service/Dockerfile": (APPLIER,), "common/runtime/src/truealpha_runtime/testing.py": ("apply_migrations.sh",), }
@pytest.mark.parametrize(("relative", "expected"), sorted(FILE_CALL_SITES.items()))
def test_the_other_call_sites_run_the_one_applier(relative: str, expected: tuple[str, ...]) -> None:
    body = (REPO_ROOT / relative).read_text(encoding="utf-8")
    for needle in expected: assert needle in body, f"{relative} no longer reaches {needle}"
def test_the_applier_ends_with_roles_and_stops_on_the_first_error() -> None: body = (REPO_ROOT / APPLIER).read_text(encoding="utf-8"); assert SHELL_CHAIN_LOOP.search(body), "the applier no longer loops over the chain"; assert 'migrations/*.sql "$db_dir"/roles.sql' in body, ( 'roles.sql must be the last file of the chain: the migrations create the relations and roles.sql carries the permanent grants over them (ci-db learned this as a failing governed-research-access contract)' ); assert "ON_ERROR_STOP=1" in body, "a failed statement must abort the run, not be skipped"
def test_the_applier_refuses_to_report_success_over_an_empty_chain(tmp_path: Path) -> None: (tmp_path / "migrations").mkdir(); (tmp_path / "roles.sql").write_text("select 1;\n"); completed = subprocess.run( ["sh", str(REPO_ROOT / APPLIER)], env={ "PATH": "/usr/bin:/bin:/usr/local/bin", "TRUEALPHA_DB_DIR": str(tmp_path), "DATABASE_URL": "postgresql://localhost:1/unreachable", }, capture_output=True, text=True, check=False, timeout=60, ); assert completed.returncode != 0, completed.stdout; assert "no .sql files" in completed.stdout + completed.stderr
RESET = "db/reset_database.sh"; TARGETS_THE_RESET_MUST_REFUSE = ( ("postgresql://postgres:hunter2@db.example.invalid:5432/truealpha", "is not a local target"), ("postgresql://postgres@127.0.0.1:5432/postgres", "maintenance database"), ("postgresql://postgres@127.0.0.1:5432/two words", "not a plain identifier"), ("postgresql://postgres@127.0.0.1:15433/truealpha", "is not a local target"), ("postgresql://postgres@localhost:15432/truealpha", "is not a local target"), ("host=127.0.0.1 dbname=truealpha", "must be a postgresql:// URI"), ("", "takes no default target"), )
@pytest.mark.parametrize(("target", "refusal"), TARGETS_THE_RESET_MUST_REFUSE)
def test_the_reset_refuses_what_it_must_never_drop(target: str, refusal: str) -> None: completed = subprocess.run( ["sh", str(REPO_ROOT / RESET)], env={"PATH": "/usr/bin:/bin:/usr/local/bin", "DATABASE_URL": target}, capture_output=True, text=True, check=False, timeout=60, ); assert completed.returncode != 0, completed.stdout; assert refusal in completed.stderr, completed.stderr
def test_the_reset_never_echoes_the_password_it_was_given() -> None: completed = subprocess.run( ["sh", str(REPO_ROOT / RESET)], env={ "PATH": "/usr/bin:/bin:/usr/local/bin", "DATABASE_URL": "postgresql://postgres:hunter2@db.example.invalid:5432/truealpha", }, capture_output=True, text=True, check=False, timeout=60, ); assert "hunter2" not in completed.stdout + completed.stderr, completed.stderr; assert "db.example.invalid" in completed.stderr, "it must still say WHICH database it refused"
LOCAL_TARGET = "db/local_target.sh"; SERVER_WRITERS = ("db/reset_database.sh", "common/runtime/src/truealpha_tools/schema_drift.py"); LOCALITY_CASES = ( ("postgresql://postgres:secret@localhost:5432/truealpha", "local"), ("postgresql://postgres@127.0.0.1:5432/truealpha", "local"), ("postgresql://user@[::1]:5432/db", "local"), ("postgresql:///truealpha?user=postgres", "local"), ("postgresql://postgres@/truealpha?host=/var/run/postgresql", "local"), ("postgres://u@db.example.invalid:15433/truealpha?sslmode=require", "remote"), ("postgresql://postgres@127.0.0.1:15433/truealpha", "remote"), ("postgresql://postgres:secret@localhost:15433/truealpha", "remote"), ("postgresql://user@[::1]:15433/db", "remote"), ("postgresql://postgres@127.0.0.1:15432/truealpha", "remote"), ("postgresql://postgres@127.0.0.1/truealpha?port=15433", "remote"), ("postgresql://postgres@127.0.0.1/truealpha?sslmode=disable&port=15433&x=y", "remote"), ("postgresql://postgres@127.0.0.1:5432,127.0.0.1:15433/truealpha", "remote"), ("postgresql://postgres@127.0.0.1/truealpha?port=5432,15433", "remote"), ("postgresql://postgres@127.0.0.1:015433/truealpha", "remote"), ("postgresql://postgres@/truealpha?host=/var/run/postgresql&port=15433", "remote"), ("postgresql://postgres@127.0.0.1/truealpha?port=1%35433", "remote"), ("postgresql://postgres@127.0.0.1:15434/truealpha", "local"), ("postgresql://postgres@127.0.0.1:5433/truealpha", "local"), ("postgresql://postgres@127.0.0.1:5432/truealpha?port=5432", "local"), ("postgresql://postgres@127.0.0.1:5432/truealpha?application_name=port=15433", "local"), ("postgresql://u:p@truealpha-postgres-staging:5432/truealpha", "remote"), ("postgresql://u@10.0.0.7/truealpha", "remote"), ("postgresql://u@localhost.evil.example/truealpha", "remote"), )
def _classify(dsn: str, **environment: str) -> subprocess.CompletedProcess[str]: return subprocess.run( ["sh", str(REPO_ROOT / LOCAL_TARGET)], input=dsn, capture_output=True, text=True, check=False, timeout=60, env={"PATH": "/usr/bin:/bin:/usr/local/bin", **environment}, )
@pytest.mark.parametrize(("dsn", "locality"), LOCALITY_CASES)
def test_the_shared_classifier_says_which_server_this_is(dsn: str, locality: str) -> None: completed = _classify(dsn); assert completed.returncode == 0, completed.stderr; parsed = dict(token.split("=", 1) for token in shlex.split(completed.stdout)); assert parsed["ta_locality"] == locality, completed.stdout
@pytest.mark.parametrize( ("dsn", "environment", "locality"), [ ("postgresql://postgres@127.0.0.1/truealpha", {"PGPORT": "15433"}, "remote"), ("postgresql://postgres@127.0.0.1/truealpha", {"PGPORT": "0015432"}, "remote"), ("postgresql://postgres@127.0.0.1:5432/truealpha", {"PGPORT": "15433"}, "local"), ("postgresql://postgres@127.0.0.1/truealpha", {"PGPORT": "5432"}, "local"), ("postgresql://postgres@127.0.0.1/truealpha", {}, "local"), ], )
def test_the_shared_classifier_reads_the_port_libpq_would_use_from_pgport( dsn: str, environment: dict[str, str], locality: str ) -> None: completed = _classify(dsn, **environment); assert completed.returncode == 0, completed.stderr; parsed = dict(token.split("=", 1) for token in shlex.split(completed.stdout)); assert parsed["ta_locality"] == locality, (dsn, environment, completed.stdout)
def test_the_shared_classifier_redacts_the_password_it_was_given() -> None: completed = _classify("postgresql://postgres:hunter2@db.example.invalid:5432/truealpha"); parsed = dict(token.split("=", 1) for token in shlex.split(completed.stdout)); assert "hunter2" not in parsed["ta_redacted"]; assert parsed["ta_redacted"] == "postgresql://postgres@db.example.invalid:5432/truealpha"
def test_the_shared_classifier_refuses_a_conninfo_without_quoting_it_back() -> None: completed = _classify("host=db.example.invalid dbname=truealpha password=hunter2"); assert completed.returncode == 2; assert "postgresql://" in completed.stderr; assert "hunter2" not in completed.stderr + completed.stdout
def test_a_value_cannot_escape_the_quoting_its_callers_eval() -> None: completed = _classify("postgresql://a'b:pw@db.example.invalid/x"); assert completed.returncode == 0, completed.stderr; parsed = dict(token.split("=", 1) for token in shlex.split(completed.stdout)); assert parsed["ta_authority"] == "a'b:pw@db.example.invalid"; assert parsed["ta_locality"] == "remote"
@pytest.mark.parametrize("relative", SERVER_WRITERS)
def test_neither_server_writer_carries_its_own_host_list(relative: str) -> None:
    body = (REPO_ROOT / relative).read_text(encoding="utf-8"); assert "local_target.sh" in body, f"{relative} no longer asks {LOCAL_TARGET} which server it is on"
    for literal in ("127.0.0.1", "localhost", "::1"): assert literal not in body, ( f"{relative} spells out {literal!r} again — 'which hosts are this machine' has one answer, in {LOCAL_TARGET}, and two copies of it drift the way the seven appliers did" )
